// RENDER KARTU BERITA KE DALAM GRID

const newsGrid   = document.getElementById("newsGrid");
const totalBadge = document.getElementById("totalBadge");

function renderNews(data) {
  newsGrid.innerHTML = "";
  data.forEach((item, index) => {
    const card = document.createElement("article");
    card.className = "news-card";
    card.setAttribute("data-index", index);

    card.innerHTML = `
      <div class="thumb-wrap">
        <img src="${item.image}" alt="${item.title}" loading="lazy">
        <span class="badge-desa">BERITA DESA</span>
      </div>
      <div class="body">
        <h3>${item.title}</h3>
        <div class="meta">
          <span>&#128197; ${item.date}</span>
          <span>&#128065; ${item.views}</span>
        </div>
        <div class="card-footer">
          <span class="btn-baca">Baca &#8594;</span>
        </div>
      </div>
    `;

    // klik kartu apa saja -> buka modal popup
    card.addEventListener("click", () => openModal(index));
    newsGrid.appendChild(card);
  });

  totalBadge.textContent = `Total ${data.length} Berita`;
}


// POP-UP DETAIL BERITA

const modalOverlay = document.getElementById("modalOverlay");
const modalImage   = document.getElementById("modalImage");
const modalTitle   = document.getElementById("modalTitle");
const modalDate    = document.getElementById("modalDate");
const modalViews   = document.getElementById("modalViews");
const modalContent = document.getElementById("modalContent");
const modalClose   = document.getElementById("modalClose");

function openModal(index) {
  const item = beritaData[index];
  modalImage.src   = item.image;
  modalImage.alt   = item.title;
  modalTitle.textContent   = item.title;
  modalDate.textContent    = item.date;
  modalViews.textContent   = item.views;
  modalContent.textContent = item.content;

  modalOverlay.classList.add("open");
  document.body.style.overflow = "hidden"; // kunci scroll halaman belakang
}

function closeModal() {
  modalOverlay.classList.remove("open");
  document.body.style.overflow = "";
}

modalClose.addEventListener("click", closeModal);

// klik area gelap di luar kotak modal -> ikut menutup
modalOverlay.addEventListener("click", (e) => {
  if (e.target === modalOverlay) closeModal();
});

// tombol Escape untuk menutup modal
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closeModal();
});


  // JAM DIGITAL BERJALAN (live clock) DI TOP BAR

const hariList = ["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"];
const bulanList = ["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];

function updateClock() {
  const now = new Date();
  const hari   = hariList[now.getDay()];
  const tgl    = String(now.getDate()).padStart(2, "0");
  const bulan  = bulanList[now.getMonth()];
  const tahun  = now.getFullYear();
  const jam    = String(now.getHours()).padStart(2, "0");
  const menit  = String(now.getMinutes()).padStart(2, "0");
  const detik  = String(now.getSeconds()).padStart(2, "0");

  document.getElementById("clockText").textContent =
    `${hari}, ${tgl} ${bulan} ${tahun} • ${jam}:${menit}:${detik} WIB`;
}
updateClock();
setInterval(updateClock, 1000);

// TOMBOL SCROLL TO TOP

const scrollBtn = document.getElementById("scrollTopBtn");

window.addEventListener("scroll", () => {
  if (window.scrollY > 400) {
    scrollBtn.classList.add("show");
  } else {
    scrollBtn.classList.remove("show");
  }
});

scrollBtn.addEventListener("click", () => {
  window.scrollTo({ top: 0, behavior: "smooth" });
});

//INISIALISASI HALAMAN
renderNews(beritaData);
